INSERT INTO crop_knowledge_base (id, crop_name, category, suitable_soil_types, ideal_ph_range, sowing_season, irrigation_schedule, nutrient_guidance, common_pests_diseases, advisory_disclaimer, created_at, updated_at)
VALUES
('22222222-4444-4444-4444-444444440001', 'Wheat', 'Grain', 'Alluvial Loam, Clay Loam', '6.0 - 7.5', 'Rabi (Late Oct - Nov)', 'Critical stages: Crown Root Initiation (21 DAS), Tillering, Jointing, Flowering, Milk stage.', 'Balanced NPK based on local soil test; split nitrogen at basal and first irrigation.', 'Yellow/Stripe rust, Aphids, Loose smut. Scout leaves weekly and consult an agronomist before spraying.', 'Reference agronomic summary; validate dosage and pesticide choice with a certified agricultural expert or Krishi Vigyan Kendra (KVK).', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('22222222-4444-4444-4444-444444440002', 'Rice (Paddy)', 'Grain', 'Clayey, Silty Loam, Alluvial', '5.5 - 7.0', 'Kharif (Jun - Jul)', 'Maintain 2-5 cm standing water during vegetative phase or adopt alternate wetting and drying.', 'Apply zinc sulfate where deficiency appears; split N across basal, active tillering, and panicle initiation.', 'Stem borer, Brown planthopper, Blast, Bacterial leaf blight.', 'Reference agronomic summary; verify pest thresholds and chemical interventions with a licensed agronomist.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('22222222-4444-4444-4444-444444440003', 'Cotton', 'Fiber', 'Black Cotton (Vertisol), Deep Loam', '6.0 - 8.0', 'Kharif (Apr - Jun)', 'Irrigate at squaring, flowering, and boll development; avoid waterlogging.', 'Monitor potassium and magnesium during boll formation; avoid excess nitrogen that invites sucking pests.', 'Pink bollworm, Whitefly, Jassids, Boll rot. Use pheromone traps for early monitoring.', 'Reference agronomic summary; always verify field thresholds with an agricultural specialist.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('22222222-4444-4444-4444-444444440004', 'Tomato', 'Vegetable', 'Well-drained Sandy Loam, Red Loam', '6.0 - 7.0', 'Year-round (region dependent)', 'Light frequent drip irrigation; avoid overhead wetting late in the day.', 'Calcium and boron support fruit set and reduce blossom-end rot; base application on soil test.', 'Early blight, Late blight, Fruit borer, Leaf curl virus (whitefly vector).', 'Reference agronomic summary; automated guidance is not a certified lab diagnosis.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('22222222-4444-4444-4444-444444440005', 'Soybean', 'Oilseed', 'Deep Loam, Black Soil', '6.0 - 7.0', 'Kharif (Jun - Jul)', 'Mainly rainfed; protective irrigation at pod initiation and grain filling improves yield stability.', 'Seed treatment with Rhizobium culture reduces nitrogen demand; supply phosphorus and sulfur as tested.', 'Girdle beetle, Semilooper, Yellow mosaic virus, Charcoal rot.', 'Reference agronomic summary; confirm local varietal and spray recommendations with KVK advisors.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
